from __future__ import annotations

import json
from pathlib import Path

from workflow.observe_storage import run_public_observations


TASK_DIR = Path(__file__).resolve().parent
REPORT_FILE = TASK_DIR / "outputs" / "public_reproduction_report.json"


def write_report(payload: dict[str, object], exit_code: int) -> int:
    REPORT_FILE.parent.mkdir(exist_ok=True)
    rendered = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT_FILE.write_text(rendered, encoding="utf-8")
    print(rendered, end="")
    return exit_code


def main() -> int:
    try:
        observations = run_public_observations()
    except Exception as exc:  # noqa: BLE001 - infrastructure is reported separately.
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    return write_report(
        {
            "schema_version": "1.0",
            "status": "workflow_completed",
            "observation": observations,
        },
        0,
    )


if __name__ == "__main__":
    raise SystemExit(main())

